// ===== NASTROYKI TESTIROVANIYA =====
const BYPASS_SCHEDULE = ['77477558162'];
const RESET_ALL_CHATS = false;
// ===================================

const raw = $input.first().json || {};
const body = raw.body || raw;

if (body.test === true) { console.log('WAZZUP TEST PING'); return []; }
if (!Array.isArray(body.messages) || body.messages.length === 0) { console.log('NO MESSAGES - skip'); return []; }

const parts = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Asia/Almaty', weekday: 'short', hour: '2-digit', minute: '2-digit', hour12: false
}).formatToParts(new Date());
const get = (t) => ((parts.find((p) => p.type === t) || {}).value || '');
const wd = get('weekday');
const minutes = parseInt(get('hour'), 10) * 60 + parseInt(get('minute'), 10);
const isEvening = ['Mon', 'Tue', 'Wed', 'Thu'].includes(wd) && minutes >= 1080;
const isMorning = ['Tue', 'Wed', 'Thu', 'Fri'].includes(wd) && minutes < 570;
const inWindow = isEvening || isMorning;

const incoming = body.messages.filter((m) => m && (m.isEcho === false || m.status === 'inbound') && m.isEcho !== true);
const m = incoming[incoming.length - 1];
if (!m) { console.log('NO INBOUND MESSAGE'); return []; }
if (m.isDeleted === true || m.isEdited === true) { console.log('EDITED/DELETED - skip'); return []; }

const chatId = m.chatId || '';
const msgId = m.messageId || '';
let text = (m.text || '').trim();
const contact = m.contact || {};
const phone = m.chatType === 'whatsapp' ? chatId : (contact.phone || chatId);

const store = $getWorkflowStaticData('global');
if (!store.chats) store.chats = {};

if (RESET_ALL_CHATS) { store.chats = {}; console.log('ALL HISTORY CLEARED'); return []; }

const digits = String(phone).replace(/\D/g, '');
const isTester = BYPASS_SCHEDULE.some((n) => {
  const d = String(n).replace(/\D/g, '');
  return d && digits.endsWith(d.slice(-10));
});

const cmd = text.toLowerCase().replace(/\s+/g, '');
if (isTester && ['/reset', '/сброс', 'сброс', '/clear'].includes(cmd)) {
  delete store.chats[chatId];
  console.log('HISTORY CLEARED for ' + chatId);
  return [];
}

if (!inWindow && !isTester) { console.log('OUTSIDE WINDOW - silent'); return []; }

const prev = store.chats[chatId];
if (msgId && prev && prev.lastMsgId === msgId) { console.log('DUPLICATE - skip'); return []; }

const st = prev || { greeted: false, lang: '', lastMsgId: '', history: [], stage: 'collecting' };
if (!Array.isArray(st.history)) st.history = [];
if (!st.stage) st.stage = 'collecting';

// --- vlozheniya ---
if (m.type && m.type !== 'text') {
  if (m.type === 'missing_call') { console.log('MISSED CALL - silent'); return []; }

  const names = {
    image: 'фото',
    video: 'видео',
    audio: 'голосовое сообщение',
    document: 'файл',
    geo: 'геолокацию',
    contact: 'контакт'
  };
  const kind = names[m.type] || 'вложение';

  if (st.stage === 'awaiting_payment' && ['image', 'document'].includes(m.type)) {
    text = '[КЛИЕНТ ПРИСЛАЛ ' + kind.toUpperCase() + ' — вероятно, квитанция об оплате. Содержимое ты не видишь и проверить не можешь]';
    console.log('RECEIPT received from ' + phone);
  } else {
    text = '[КЛИЕНТ ПРИСЛАЛ ' + kind.toUpperCase() + '. Содержимое ты НЕ видишь и НЕ слышишь. Подтверди получение, скажи что передашь специалисту, и продолжай собирать вводные текстом]';
    console.log('ATTACHMENT ' + m.type + ' from ' + phone);
  }
}
if (!text) { console.log('EMPTY TEXT - skip'); return []; }

st.lastMsgId = msgId;

const historyText = st.history.length
  ? st.history.slice(-16).map((h) => (h.role === 'client' ? 'Клиент: ' : 'Ардак: ') + h.text).join('\n')
  : '(это начало диалога)';

st.history.push({ role: 'client', text });
if (st.history.length > 26) st.history = st.history.slice(-26);
store.chats[chatId] = st;

const keys = Object.keys(store.chats);
if (keys.length > 300) keys.slice(0, keys.length - 300).forEach((k) => delete store.chats[k]);

return [{
  json: {
    chatId,
    chatType: m.chatType || 'whatsapp',
    channelId: m.channelId || '',
    clientText: text,
    clientName: contact.name || '',
    phone,
    mode: st.greeted ? 'continue' : 'first',
    lang: st.lang || '',
    stage: st.stage,
    historyText
  }
}];

const gate = $('Parse & Gate').first().json;

let crm = {};
try {
  const r = $input.first().json || {};
  crm = typeof r === 'string' ? JSON.parse(r) : (typeof r.data === 'string' ? JSON.parse(r.data) : r);
} catch (e) {}

const contacts = ((crm._embedded || {}).contacts) || [];
const c = contacts[0] || {};
const leads = ((c._embedded || {}).leads) || [];

return [{
  json: {
    chatId: gate.chatId,
    chatType: gate.chatType,
    channelId: gate.channelId,
    clientText: gate.clientText,
    clientName: gate.clientName || c.name || '',
    phone: gate.phone,
    mode: gate.mode,
    lang: gate.lang,
    stage: gate.stage,
    historyText: gate.historyText,
    leadId: (leads[0] || {}).id || null
  }
}];

// ===== NASTROYKI ZAPUSKA =====
const TEST_NUMBERS = ['77477558162'];
const LIVE_FOR_EVERYONE = true;
const MANAGER_WHATSAPP = '77477388216';
// =============================

const ctx = $('Build Context').first().json;
const rawOut = ($input.first().json.text || '').trim();

let lang = '';
let reply = '';
let stage = ctx.stage || 'collecting';
let summary = '';

try {
  const cleaned = rawOut.replace(/```json/gi, '').replace(/```/g, '').trim();
  const s = cleaned.indexOf('{');
  const e = cleaned.lastIndexOf('}');
  const p = JSON.parse(cleaned.slice(s, e + 1));
  lang = String(p.lang || '').toLowerCase();
  reply = String(p.reply || '').trim();
  summary = String(p.summary || '').trim();
  if (['collecting', 'selling', 'awaiting_payment', 'paid'].includes(p.stage)) stage = p.stage;
} catch (err) {
  reply = rawOut;
}

if (!reply) { console.log('EMPTY REPLY - skip'); return []; }

const store = $getWorkflowStaticData('global');
if (!store.chats) store.chats = {};
const st = store.chats[ctx.chatId] || { greeted: false, lang: '', lastMsgId: '', history: [], stage: 'collecting' };
if (!Array.isArray(st.history)) st.history = [];

st.greeted = true;
st.stage = stage;
if (ctx.mode === 'continue' && ['kk', 'ru'].includes(lang)) st.lang = lang;
st.history.push({ role: 'bot', text: reply });
if (st.history.length > 26) st.history = st.history.slice(-26);

const shouldNotify = stage === 'paid' && summary && st.notified !== true;
if (shouldNotify) st.notified = true;

store.chats[ctx.chatId] = st;

const digits = String(ctx.phone || '').replace(/\D/g, '');
const allowed = LIVE_FOR_EVERYONE || TEST_NUMBERS.some((n) => {
  const d = String(n).replace(/\D/g, '');
  return d && digits.endsWith(d.slice(-10));
});

console.log('ARDAK -> ' + ctx.phone + ' [' + stage + '/' + (st.lang || '?') + ']: ' + reply);

if (!allowed) { console.log('NOMER NE V SPISKE - ne otpravleno'); return []; }

const out = [{
  json: { channelId: ctx.channelId, chatId: ctx.chatId, chatType: ctx.chatType, text: reply }
}];

if (shouldNotify) {
  const note = '\uD83D\uDD14 НОЧНАЯ ЗАЯВКА С ПРЕДОПЛАТОЙ\n\n'
    + 'Клиент: ' + (ctx.clientName || 'без имени') + '\n'
    + 'Номер: +' + digits + '\n\n'
    + summary + '\n\n'
    + '⚠️ Оплата НЕ проверена автоматически. Клиент прислал скриншот — сверьте поступление 3000 тенге в Kaspi перед подтверждением.';
  out.push({
    json: { channelId: ctx.channelId, chatId: MANAGER_WHATSAPP, chatType: 'whatsapp', text: note }
  });
  console.log('MANAGER NOTIFIED -> ' + MANAGER_WHATSAPP);
}

return out;

const ctx = $('Build Context').first().json;
const rawOut = ($input.first().json.text || '').trim();

let stage = '';
let summary = '';
try {
  const cleaned = rawOut.replace(/```json/gi, '').replace(/```/g, '').trim();
  const s = cleaned.indexOf('{');
  const e = cleaned.lastIndexOf('}');
  const p = JSON.parse(cleaned.slice(s, e + 1));
  stage = String(p.stage || '');
  summary = String(p.summary || '').trim();
} catch (err) {}

if (stage !== 'paid' || !summary) return [];

if (!ctx.leadId) {
  console.log('NET SDELKI V CRM po nomeru ' + ctx.phone + ' - primechanie ne sozdano');
  return [];
}

const store = $getWorkflowStaticData('global');
if (!store.chats) store.chats = {};
const st = store.chats[ctx.chatId] || {};
if (st.crmNoted === true) { console.log('CRM NOTE uzhe sozdano'); return []; }
st.crmNoted = true;
store.chats[ctx.chatId] = st;

const text = 'Заявка принята ночным AI-помощником (клиенту представляется как Ардак)\n\n'
  + summary
  + '\n\nКлиент прислал скриншот предоплаты 3000 тенге. Автоматически оплата НЕ проверена — сверьте поступление в Kaspi перед подтверждением записи.';

return [{ json: { leadId: ctx.leadId, text } }];
